import{_ as d,a0 as r,w as n,s as p,I as o,x as s,a1 as a,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Bash 5.0 發佈及其新功能 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 5.0 發佈及其新功能 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 5.0 發佈及其新功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 5.0 發佈及其新功能 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190109 Bash 5.0 Released with New Features","title":"Bash 5.0 發佈及其新功能","tag":"201901","desc":""},"relativePath":"201901/20190109 Bash 5.0 Released with New Features.md","filePath":"[post].md"}'),h={name:"201901/20190109 Bash 5.0 Released with New Features.md"};function u(b,e,f,m,g,B){const t=r("Link");return n(),p("div",null,[e[23]||(e[23]=o("h1",{id:"bash-5-0-發佈及其新功能",tabindex:"-1"},[s("Bash 5.0 發佈及其新功能 "),o("a",{class:"header-anchor",href:"#bash-5-0-發佈及其新功能","aria-label":"Permalink to “Bash 5.0 發佈及其新功能”"},"​")],-1)),o("p",null,[a(t,{href:"https://lists.gnu.org/archive/html/bug-bash/2019-01/msg00063.html"},{default:l(()=>[...e[0]||(e[0]=[s("郵件列表",-1)])]),_:1}),e[1]||(e[1]=s("證實最近發佈了 Bash-5.0。而且，令人興奮的是它還有新的功能和變量。",-1))]),o("p",null,[e[3]||(e[3]=s("如果你一直在使用 Bash 4.4.XX，那麼你一定會喜歡 ",-1)),a(t,{href:"https://www.gnu.org/software/bash/"},{default:l(()=>[...e[2]||(e[2]=[s("Bash",-1)])]),_:1}),e[4]||(e[4]=s(" 的第五個主要版本。",-1))]),e[24]||(e[24]=i('<p>第五個版本側重於新的 shell 變量和許多重大漏洞修復。它還引入了一些新功能，以及一些與 bash-4.4 不兼容的更改。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/bash-logo.jpg?resize=800%2C450&amp;ssl=1" alt="Bash logo"></p><h3 id="新功能怎麼樣" tabindex="-1">新功能怎麼樣？ <a class="header-anchor" href="#新功能怎麼樣" aria-label="Permalink to “新功能怎麼樣？”">​</a></h3><p>在郵件列表解釋了此版本中修復的 bug：</p><blockquote><p>此版本修復了 bash-4.4 中的幾個主要錯誤，並引入了幾個新功能。最重要的 bug 修復是對 nameref 變量的解析以及通過模糊測試發現的許多潛在的內存越界錯誤。在為了符合 Posix 標準解釋而不進行單詞拆分的上下文中，對 <code>$@</code> 和 <code>$*</code> 的展開做了許多改變，另外還有解決極端情況中 Posix 一致性的修改。</p></blockquote><p>它還引入了一些新功能。根據其發佈説明，最值得注意的新功能是幾個新的 shell 變量：</p><blockquote><p><code>BASH_ARGV0</code>、<code>EPOCHSECONDS</code> 和 <code>EPOCHREALTIME</code>。內置命令 <code>history</code> 可以刪除指定範圍的條目，並能將負數理解為從歷史末端開始的偏移量。有一個選項允許局部變量繼承前一個範圍內具有相同名稱的變量的值。有一個新的 shell 選項，在啓用它時，會導致 shell 只嘗試一次擴展關聯數組下標（這在算術表達式中使用時會出現問題）。<code>globasciiranges</code> 這個 shell 選項現在默認啓用。可以在配置時默認關閉它。</p></blockquote><h3 id="bash-4-4-和-bash-5-0-之間有哪些變化" tabindex="-1">Bash-4.4 和 Bash-5.0 之間有哪些變化？ <a class="header-anchor" href="#bash-4-4-和-bash-5-0-之間有哪些變化" aria-label="Permalink to “Bash-4.4 和 Bash-5.0 之間有哪些變化？”">​</a></h3><p>其更新日誌提到了不兼容的更改和所支持的 readline 版本歷史記錄。它是這麼説的：</p><blockquote><p>bash-4.4 和 bash-5.0 之間存在一些不兼容的變化。儘管我已經儘量最小化兼容性問題，但是對 <code>nameref</code> 變量解析的更改意味着對變量名引用的某些使用會有不同的行為。默認情況下，如果啓用了擴展調試模式，shell 僅在啓動時設置 <code>BASH_ARGC</code> 和 <code>BASH_ARGV</code>。它被無條件地設置是一個疏忽，並且在腳本傳遞大量參數時會導致性能問題。</p><p>如果需要，可以將 Bash 鏈接到已安裝的 Readline 庫，而不是 <code>lib/readline</code> 中的私有版本。只有 readline-8.0 及更高版本能夠提供 bash-5.0 所需的所有符號。早期版本的 Readline 庫無法正常工作。</p></blockquote><p>我相信一些添加的功能/變量非常有用。我最喜歡的一些是：</p><ul><li>有一個新的（默認情況下禁用，文檔中沒有説明）shell 選項，用於在運行時啓用/禁用向 syslog 發送歷史記錄。</li><li>正如文檔一直所説的那樣，除非 shell 處於調試模式，否則它不會在啓動時自動設置 <code>BASH_ARGC</code> 和 <code>BASH_ARGV</code>，但如果腳本在上層引用它們且沒有啓用調試模式，那麼 shell 將動態創建它們。</li><li>現在可以使用 <code>-d start-end</code> 刪除指定範圍的 <code>history</code> 條目。</li><li>如果啓用了作業控制的非交互式 shell 檢測到前台作業因 SIGINT 而死亡，則其行為就像接收到 SIGINT 一樣。</li><li><code>BASH_ARGV0</code>：一個新變量，擴展為 <code>$0</code>，並在賦值時設置為 <code>$0</code>。</li></ul>',12)),o("p",null,[e[6]||(e[6]=s("要查看完整的更改和功能列表，請參閲",-1)),a(t,{href:"https://lists.gnu.org/archive/html/bug-bash/2019-01/msg00063.html"},{default:l(()=>[...e[5]||(e[5]=[s("郵件列表文章",-1)])]),_:1}),e[7]||(e[7]=s("。",-1))]),e[25]||(e[25]=i('<h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你可以使用下面的命令檢查你當前的 Bash 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash --version</span></span></code></pre></div><p>你很可能安裝了 Bash 4.4。如果你想獲得新版本，我建議等待你的發行版提供它。</p><p>你怎麼看待 Bash-5.0 發佈？你在使用其他 bash 的替代品麼？如果有的話，這個更新會改變你的想法麼？</p><p>請在下面的評論中告訴我們你的想法。</p><hr>',7)),o("p",null,[e[9]||(e[9]=s("via: ",-1)),a(t,{href:"https://itsfoss.com/bash-5-release"},{default:l(()=>[...e[8]||(e[8]=[s("https://itsfoss.com/bash-5-release",-1)])]),_:1})]),o("p",null,[e[14]||(e[14]=s("作者：",-1)),a(t,{href:"https://itsfoss.com/author/ankush/"},{default:l(()=>[...e[10]||(e[10]=[s("Ankush Das",-1)])]),_:1}),e[15]||(e[15]=s(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[11]||(e[11]=[s("lujun9972",-1)])]),_:1}),e[16]||(e[16]=s(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:l(()=>[...e[12]||(e[12]=[s("geekpi",-1)])]),_:1}),e[17]||(e[17]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[13]||(e[13]=[s("wxy",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[18]||(e[18]=[s("LCTT",-1)])]),_:1}),e[21]||(e[21]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[19]||(e[19]=[s("Linux中國",-1)])]),_:1}),e[22]||(e[22]=s(" 榮譽推出",-1))])])}const A=d(h,[["render",u]]);export{C as __pageData,A as default};
